def climbStairs(n):
    a, b = 1, 1
    for _ in range(n - 1):
        a, b = b, a + b   # f(i)=f(i-1)+f(i-2)
    return b

def rob(nums):
    prev, cur = 0, 0
    for x in nums:
        prev, cur = cur, max(cur, prev + x)   # 不偷 cur / 偷 prev+x
    return cur

def coinChange(coins, amount):
    INF = float('inf')
    dp = [0] + [INF] * amount
    for j in range(1, amount + 1):
        for c in coins:
            if c <= j and dp[j - c] + 1 < dp[j]:
                dp[j] = dp[j - c] + 1   # 用一枚 c 面额
    return -1 if dp[amount] == INF else dp[amount]

def lengthOfLIS(nums):
    tails = []
    for x in nums:
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(x)      # x 可延长子序列
        else:
            tails[lo] = x        # 换更小结尾更优
    return len(tails)

def longestCommonSubsequence(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1     # 末字符匹配延长
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[m][n]

def maxSubArray(nums):
    pre, ans = 0, float('-inf')
    for x in nums:
        pre = max(pre + x, x)   # 以 x 结尾的最大和
        ans = max(ans, pre)     # 记录历史最优
    return ans

def longestPalindrome(s):
    def expand(l, r):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        return l + 1, r - 1      # 回退到合法区间
    start, end = 0, 0
    for i in range(len(s)):
        for l, r in (expand(i, i), expand(i, i + 1)):   # 奇偶中心
            if r - l > end - start:
                start, end = l, r
    return s[start:end + 1]

def maxProfit(prices):
    lo, ans = float('inf'), 0
    for p in prices:
        lo = min(lo, p)        # 历史最低买入价
        ans = max(ans, p - lo) # 当天卖出的利润
    return ans

def canPartition(nums):
    total = sum(nums)
    if total % 2:
        return False
    target = total // 2
    dp = [False] * (target + 1)
    dp[0] = True
    for x in nums:
        for j in range(target, x - 1, -1):   # 倒序只用一次
            if dp[j - x]:
                dp[j] = True
    return dp[target]

def rob(nums):
    if len(nums) == 1:
        return nums[0]
    def line(a):
        prev, cur = 0, 0
        for x in a:
            prev, cur = cur, max(cur, prev + x)   # 线性打家劫舍
        return cur
    return max(line(nums[1:]), line(nums[:-1]))   # 拆两段取最大

def maxProduct(nums):
    ans = maxP = minP = nums[0]
    for x in nums[1:]:
        maxP, minP = max(maxP * x, minP * x, x), min(maxP * x, minP * x, x)
        ans = max(ans, maxP)   # 负数可能翻盘，双端都记
    return ans

def uniquePaths(m, n):
    dp = [1] * n              # 首行全 1
    for _ in range(1, m):
        for j in range(1, n):
            dp[j] += dp[j - 1]   # 上方 + 左方
    return dp[-1]

def minPathSum(grid):
    m, n = len(grid), len(grid[0])
    dp = [float('inf')] * n
    dp[0] = 0
    for i in range(m):
        dp[0] += grid[i][0]   # 左边界只能来自上
        for j in range(1, n):
            dp[j] = min(dp[j], dp[j - 1]) + grid[i][j]   # 上与左取小
    return dp[-1]

def maxProfit(prices):
    ans = 0
    for i in range(1, len(prices)):
        ans += max(0, prices[i] - prices[i - 1])   # 只收上涨段
    return ans

def wordBreak(s, wordDict):
    ws = set(wordDict)
    n = len(s)
    dp = [True] + [False] * n
    for i in range(1, n + 1):
        for j in range(i):
            if dp[j] and s[j:i] in ws:   # 最后一段落在字典里
                dp[i] = True
                break
    return dp[n]

def numSquares(n):
    INF = float('inf')
    dp = [0] + [INF] * n
    for j in range(1, n + 1):
        k = 1
        while k * k <= j:
            if dp[j - k * k] + 1 < dp[j]:
                dp[j] = dp[j - k * k] + 1   # 用一枚 k*k
            k += 1
    return dp[n]

def change(amount, coins):
    dp = [1] + [0] * amount
    for c in coins:
        for j in range(c, amount + 1):
            dp[j] += dp[j - c]   # 追加一枚 c 的组合数
    return dp[amount]

def minDistance(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i            # 删光 a
    for j in range(n + 1):
        dp[0][j] = j            # 插出 b
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = min(dp[i - 1][j - 1], dp[i - 1][j], dp[i][j - 1]) + 1
    return dp[m][n]

def isMatch(s, p):
    m, n = len(s), len(p)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True
    for j in range(2, n + 1):
        dp[0][j] = p[j - 1] == '*' and dp[0][j - 2]   # 星号消前字符
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                dp[i][j] = dp[i][j - 2] or (dp[i - 1][j] and p[j - 2] in (s[i - 1], '.'))
            else:
                dp[i][j] = dp[i - 1][j - 1] and p[j - 1] in (s[i - 1], '.')
    return dp[m][n]

def longestValidParentheses(s):
    stack = [-1]             # 栈底垫分界下标
    ans = 0
    for i, c in enumerate(s):
        if c == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)          # 未匹配，新分界
            else:
                ans = max(ans, i - stack[-1])   # 当前有效段长
    return ans

def findTargetSumWays(nums, target):
    total = sum(nums)
    if (target + total) % 2 or abs(target) > total:
        return 0              # 凑不出整数子集和
    w = (target + total) // 2
    dp = [1] + [0] * w
    for x in nums:
        for j in range(w, x - 1, -1):   # 倒序每数只用一次
            dp[j] += dp[j - x]
    return dp[w]
